body {
margin: 15px;
color: #603000;
}
.panel {
background-color: transparent;
padding: 0;
/* background-color: #ffe0b0; */
/* padding: .5em 2em .5em 1em; */
/* margin: 5px; */
/* border: 5px solid var(--common-green); */
/* border-radius: 15px; */
box-shadow: none;
border: none;
}
header {
/* padding-right: 5em; */
}
footer {
text-align: center;
padding-right: 1em;
margin-bottom: 3em;
}
input-container { display: none; }
output-container { display: none; }
progress-container { display: none; }
.initial_hide { display: none; }
.error {
font-weight: bold;
font-size: 150%;
color: #ff0000;
}
.path {
font-family: monospace;
}
.code {
font-family: monospace;
font-weight: bold;
white-space: pre;
}
.ach,.warn,.note,.booktitle {
/* font-style: italic; */
font-weight: 650;
}
.pts, .strong {
font-weight: bold;
}
.ach_yes,.ms_yes,.pt_yes {
color: #004000;
}
.ach_yes:before,.ms_yes:before {
content: "\2714 ";
margin-right: 3px;
}
.ach_no,.ms_no,.pt_no {
color: #c00000;
}
.ach_no:before,.ach_imp:before,.ms_no:before,.ms_imp:before {
content: "\2718 ";
margin-right: 3px;
}
.ach_imp,.ms_imp,.pt_imp {
color: #888;
}
.ach_list {
list-style: none;
padding-left: 50px;
margin-top: 0px;
margin-bottom: 4px;
text-indent: -15px;
}
.result:before {
content: "\25c8 ";
margin-right: 3px;
}
.result {
padding-left: 0px;
color: #222222;
}
.explain:before {
content: "* ";
margin-right: 3px;
}
.explain {
padding-left: 15px;
/* font-style: italic; */
font-weight: 600;
}
.need:before,.warn:before {
content: "! ";
font-weight: bold;
margin-right: 3px;
}
.need {
margin-left: 38px;
}
.need > ul, .need > ol {
margin-left: 3.5em;
margin-top: 0px;
}
.need ol, .need ul {
padding-left: 1.5em;
}
ol.outer, ul.outer {
margin-top: 0;
padding-left: 3em;
margin: 0 !important;
}
ol.compact, ul.compact {
margin-top: 0;
padding-left: 1em;
margin: 0 !important;
}
table.output {
border: none;
border-collapse: collapse;
width: 100%;
table-layout: fixed;
}
.output td {
vertical-align: top;
}
tr td:not(:first-child) {
border-left: 1px solid;
}
PlayerList {
